from pydantic import BaseModel, Field


class TaskPlan(BaseModel):
    """Structured plan generated by Project Manager & Repo Analyst."""
    task_summary: str = Field(description="Brief summary of the engineering task")
    acceptance_criteria: list[str] = Field(description="Measurable conditions for task completion")
    files_to_inspect: list[str] = Field(description="Target repository files to inspect/modify")
    risks: list[str] = Field(description="Potential security or stability risks")
    test_plan: list[str] = Field(description="Test cases to validate the patch")


class PatchProposal(BaseModel):
    """Proposed code modification generated by Developer Agent."""
    explanation: str = Field(description="Explanation of what changed and why")
    diff: str = Field(description="Unified Git diff starting with diff --git or standard patch format")


class ReviewReport(BaseModel):
    """Security and quality audit generated by Reviewer Agent."""
    passed: bool = Field(description="True if patch meets quality and security requirements")
    security_concerns: list[str] = Field(default_factory=list, description="Secrets, dangerous imports, or SQLi")
    reviewer_comments: str = Field(description="Summary of code review findings")
